loader = RealDataLoader()
all_pois = loader.fetch_pois()
by_name = {p.name: p for p in all_pois}

anchors = [by_name[n] for n in ["전포공구길", "부산시민공원", "서면먹자골목", "삼광사"] if n in by_name]
center_lat = sum(p.lat for p in anchors) / len(anchors)
center_lng = sum(p.lng for p in anchors) / len(anchors)

from collections import defaultdict
by_placetype = defaultdict(list)
for m in VALID_MATCHES:
    poi = by_name.get(m["name"])
    if not poi:
        continue
    dist = haversine_km(center_lat, center_lng, poi.lat, poi.lng)
    by_placetype[m["placetype"]].append((poi.name, poi.category, m["sk_poi_id"], dist))

# 유형별 최소 2개 보장 + 전체 30개가 되도록 가까운 순 배분
MIN_PER_TYPE = 2
TOTAL_TARGET = 30

final_30 = []
remaining_pool = []

for pt in ["NATURE", "CULTURE", "ALLEY", "TEMPLE", "EXPERIENCE", "BEACH"]:
    items = sorted(by_placetype[pt], key=lambda x: x[3])
    for item in items[:MIN_PER_TYPE]:
        final_30.append((pt, *item))
    remaining_pool.extend((pt, *item) for item in items[MIN_PER_TYPE:])

remaining_pool.sort(key=lambda x: x[4])
while len(final_30) < TOTAL_TARGET and remaining_pool:
    final_30.append(remaining_pool.pop(0))

final_30.sort(key=lambda x: x[4])

print(f"=== 최종 {len(final_30)}곳 ===\n")
print(f"{'유형':<12}{'이름':<25}{'카테고리':<15}{'SK poiId':<12}{'거리(km)'}")
for pt, name, cat, sk_id, dist in final_30:
    print(f"{pt:<12}{name:<25}{cat:<15}{sk_id:<12}{dist:.2f}")

print("\n=== 유형별 개수 ===")
from collections import Counter
type_counts = Counter(row[0] for row in final_30)
for pt, count in type_counts.items():
    print(f"  {pt}: {count}개")